```rust
/// `picks` with its first replaced by `unoffered`, or `unoffered` alone when there are none.
fn with_unoffered<T: Clone>(picks: Option<&[T]>, unoffered: T) -> Vec<T> {
    let mut out: Vec<T> = picks.unwrap_or_default().to_vec();
    match out.first_mut() {
        Some(first) => *first = unoffered,
        None => out.push(unoffered),
    }
    out
}

/// #1694: `chosen`, an action `legal_actions` lists `player`, with one declared choice made impossible,
/// each with the seat that sends it: a `play` naming a target, a mode, a zone, a Tribute, a Plague source
/// or a face-down timing nothing offers, or a negative X (§10.5 step 1, R81, R90,
/// `play_choices::why_choices_refused`, R454); an `activate` naming an ability the card lacks, a target,
/// a mode or a Tribute nothing offers, and its `activatePower` alias aimed at nothing (R384,
/// `activate::why_activate_refused`); a `mulligan` keeping a card the seat was not dealt, and a second
/// answer from the other seat once it has answered (R265, `setup::why_mulligan_refused`). Each is
/// impossible by construction, never merely unlisted, since R90's bound lists only a slice of the legal
/// combinations. Empty for any other action (an answer is `malformed_answers`').
pub fn malformed_actions(
    state: &GameState,
    player: PlayerId,
    chosen: &ActionBody,
) -> Vec<(&'static str, PlayerId, ActionBody)> {
    let unoffered_pick = || Selection::Instance {
        instance_id: UNOFFERED_INSTANCE_ID.to_string(),
    };
    let unoffered_id = || UNOFFERED_INSTANCE_ID.to_string();
    let mut out: Vec<(&'static str, PlayerId, ActionBody)> = Vec::new();
    if let Some(play) = PlayAction::from_body(chosen) {
        let mut push = |name: &'static str, forged: PlayAction| out.push((name, player, forged.into_body()));
        push(UNOFFERED_TARGET_ACTION, PlayAction { targets: Some(with_unoffered(play.targets.as_deref(), unoffered_pick())), ..play.clone() });
        push(UNOFFERED_MODE_ACTION, PlayAction { modes: Some(with_unoffered(play.modes.as_deref(), UNOFFERED_MODE.to_string())), ..play.clone() });
        push(UNOFFERED_ZONE_ACTION, PlayAction { zone: Some(ZoneChoice { row: play.zone.map_or(Row::Units, |zone| zone.row), lane: UNOFFERED_LANE }), ..play.clone() });
        // R43: an X a cost hook fixes is ignored whatever the play names, so only a chosen X is forged.
        if play.x.is_some() {
            push(NEGATIVE_X_ACTION, PlayAction { x: Some(NEGATIVE_X), ..play.clone() });
        }
        push(UNOFFERED_TRIBUTE_ACTION, PlayAction { tributes: Some(with_unoffered(play.tributes.as_deref(), unoffered_id())), ..play.clone() });
        push(UNOFFERED_PLAGUE_ACTION, PlayAction { plague: Some(PlagueSpend { from: unoffered_id(), tokens: MIN_PLAGUE_PAYMENT }), ..play.clone() });
        push(UNOFFERED_REVEAL_ACTION, PlayAction { face_down: Some(UNOFFERED_REVEAL), ..play });
    }
    if let Some(activate) = ActivateAction::from_body(chosen) {
        let mut push = |name: &'static str, forged: ActionBody| out.push((name, player, forged));
        push(UNOFFERED_ABILITY_ACTION, ActivateAction { ability: Some(UNOFFERED_ABILITY.to_string()), ..activate.clone() }.into_body());
        push(UNOFFERED_TARGET_ACTION, ActivateAction { targets: Some(with_unoffered(activate.targets.as_deref(), unoffered_pick())), ..activate.clone() }.into_body());
        push(UNOFFERED_MODE_ACTION, ActivateAction { modes: Some(with_unoffered(activate.modes.as_deref(), UNOFFERED_MODE.to_string())), ..activate.clone() }.into_body());
        push(UNOFFERED_TRIBUTE_ACTION, ActivateAction { tributes: Some(with_unoffered(activate.tributes.as_deref(), unoffered_id())), ..activate.clone() }.into_body());
        push(UNOFFERED_POWER_TARGET_ACTION, ActionBody::ActivatePower { instance_id: activate.instance_id.clone(), targets: Some(with_unoffered(activate.targets.as_deref(), unoffered_pick())) });
    }
    if let ActionBody::Mulligan { keep } = chosen {
        out.push((UNDEALT_KEEP_ACTION, player, ActionBody::Mulligan { keep: with_unoffered(Some(keep.as_slice()), unoffered_id()) }));
        let other = opponent_of(player);
        if state.mulligan.is_some() && !crate::setup::mulligan_owed(state).contains(&other) {
            out.push((ANSWERED_MULLIGAN_ACTION, other, ActionBody::Mulligan { keep: Vec::new() }));
        }
    }
    out
}
```

